-- 视频号字幕定向清理：97 条导出快照候选，不删除视频行。
-- 已核对生产 mysql-import.mjs 使用中文字段名。
-- 执行前停止三台采集程序并确认备份表名未被其他操作占用。
-- 适用 MySQL InnoDB；先核对下面的 ENGINE 查询。
-- 本文件默认 ROLLBACK，不会保留清理结果。
-- 需在同一连接完整执行。确认预览后，将末尾 ROLLBACK 改为 COMMIT 再执行。
-- 不重置 Redis，不删除本地字幕缓存，不修改清洗统计。
USE `social`;

SELECT TABLE_NAME, ENGINE
FROM information_schema.TABLES
WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'ods_social_media_post';
-- 如 ENGINE 不是 InnoDB，停止执行，事务回滚无法保证。

DROP TEMPORARY TABLE IF EXISTS `tmp_channels_subtitle_candidates_20261008`;
CREATE TEMPORARY TABLE `tmp_channels_subtitle_candidates_20261008` (
    `id` DECIMAL(20,0) NOT NULL PRIMARY KEY,
    `original_sha256` CHAR(64) CHARACTER SET ascii NOT NULL
);

-- 预览：只匹配导出快照的原字幕；已被修正的内容不匹配，不会清空。
SELECT p.`id`, p.`关键词`, p.`文章标题`, p.`文章视频内容`
FROM `ods_social_media_post` p
JOIN `tmp_channels_subtitle_candidates_20261008` t ON t.`id` = p.`id`
WHERE p.`平台` = '微信视频号'
  AND p.`项目` = '全国地产设计产品力监测'
  AND LOCATE('全国地产设计产品力监测', p.`文章视频内容`) > 0
  AND SHA2(CONVERT(p.`文章视频内容` USING utf8mb4), 256) = t.`original_sha256`;

-- DDL 放在事务之前；备份表自身会保留，默认回滚后本轮备份数据为空。
CREATE TABLE IF NOT EXISTS `bak_channels_subtitle_20261008_97`
LIKE `ods_social_media_post`;

START TRANSACTION;

-- 先锁定仍与原快照相符的候选。
SELECT p.`id`
FROM `ods_social_media_post` p
JOIN `tmp_channels_subtitle_candidates_20261008` t ON t.`id` = p.`id`
WHERE p.`平台` = '微信视频号'
  AND p.`项目` = '全国地产设计产品力监测'
  AND LOCATE('全国地产设计产品力监测', p.`文章视频内容`) > 0
  AND SHA2(CONVERT(p.`文章视频内容` USING utf8mb4), 256) = t.`original_sha256`
FOR UPDATE;

SELECT p.*
FROM `ods_social_media_post` p
JOIN `tmp_channels_subtitle_candidates_20261008` t ON t.`id` = p.`id`
WHERE p.`平台` = '微信视频号'
  AND p.`项目` = '全国地产设计产品力监测'
  AND LOCATE('全国地产设计产品力监测', p.`文章视频内容`) > 0
  AND SHA2(CONVERT(p.`文章视频内容` USING utf8mb4), 256) = t.`original_sha256`;

-- 必须同时匹配候选原文哈希和已备份原文；只改变字幕一个字段。
UPDATE `ods_social_media_post` p
JOIN `tmp_channels_subtitle_candidates_20261008` t ON t.`id` = p.`id`
JOIN `bak_channels_subtitle_20261008_97` b ON b.`id` = p.`id`
SET p.`文章视频内容` = ''
WHERE p.`平台` = '微信视频号'
  AND p.`项目` = '全国地产设计产品力监测'
  AND LOCATE('全国地产设计产品力监测', p.`文章视频内容`) > 0
  AND SHA2(CONVERT(p.`文章视频内容` USING utf8mb4), 256) = t.`original_sha256`
  AND SHA2(CONVERT(b.`文章视频内容` USING utf8mb4), 256) = t.`original_sha256`;

SET @cleared_rows = ROW_COUNT();
SELECT @cleared_rows AS `本轮清空字幕条数`,
       (SELECT COUNT(*) FROM `tmp_channels_subtitle_candidates_20261008`) AS `导出候选数`;

-- 默认演练回滚；备份插入和清空字幕均不保留。
ROLLBACK;
-- 正式清理：人工核对预览后，把上面的 ROLLBACK 替换为 COMMIT。
-- 如果任何语句报错，立即 ROLLBACK 并停止，不要继续提交。

-- 如正式提交后需要恢复：
-- 停止采集，另开事务，仅恢复仍为空且备份哈希匹配的字幕。
